/*
f = abcabbcd
        where
        `abc`: ℝ
        ab: ℝ
        bc: ℝ
        d: ℝ 
*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>
#include "type_helper.h"

using namespace iheartmesh;
struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    DT f;

    heartlib(
        const double & abc,
        const double & ab,
        const double & bc,
        const double & d)
    {

        // f = abcabbcd
        f = abc * ab * bc * d;
    }
};

outputs.matlab:
function output = heartlib(abc, ab, bc, d)
% output = heartlib(abc, ab, bc, d)
%
%    f = abcabbcd
%            where
%            `abc`: ℝ
%            ab: ℝ
%            bc: ℝ
%            d: ℝ 
    assert(numel(abc) == 1);
    assert(numel(ab) == 1);
    assert(numel(bc) == 1);
    assert(numel(d) == 1);

    % f = abcabbcd

    f = abc * ab * bc * d;
    output.f = f;
end

